let saved={};try{saved=JSON.parse(localStorage.getItem('arc-library-v1')||'{}')}catch(e){};let favorites=new Set(Array.isArray(saved.favorites)?saved.favorites:['orbit','field-notes','sonder']);let userTags=saved.tags||{};let collections=Array.isArray(saved.collections)?saved.collections:[];let collection='all',fileType='all',selectedId='orbit',view='grid',sort='recent';let demoState=new URLSearchParams(location.search).get('state')||'ready';let toastTimer;let returnFocus=null;
