function tagsOf(a){return [...new Set([...a.tags,...(userTags[a.id]||[])])]}function selected(){return assets.find(a=>a.id===selectedId)||assets[0]}function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
