function openDialog(id){returnFocus=document.activeElement;$('#'+id).showModal()}function closeDialog(id){$('#'+id).close();if(returnFocus&&returnFocus.isConnected)returnFocus.focus()}function openPreview(){let a=selected();$('#previewTitle').textContent=a.name;$('#previewImage').src=`../assets/art/${a.id}.svg`;$('#previewImage').alt=a.name+' original artwork';$('#previewMeta').textContent=`${a.type} / ${a.dimensions} / ${a.size.toFixed(1)} MB`;openDialog('previewDialog')}
