$('#assetGrid').addEventListener('dblclick',e=>{let b=e.target.closest('[data-select]');if(b){selectedId=b.dataset.select;openPreview()}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#inspector').classList.remove('open');return}if(e.ctrlKey||e.metaKey||e.altKey||e.target.matches('input,textarea,select')||$$('dialog[open]').length)return;if(e.key==='/'){e.preventDefault();$('#search').focus()}else if(e.key.toLowerCase()==='f'){e.preventDefault();toggleFavorite(selectedId)}else if(e.key.toLowerCase()==='g'){e.preventDefault();view=view==='grid'?'list':'grid';render();toast(view==='grid'?'Grid view':'List view')}else if(e.code==='Space'&&!e.target.closest('button,a,[role=button]')){e.preventDefault();openPreview()}});$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d.id)}}));
